"""Demo-mode provider. It is NOT an LLM: it picks tools with keyword rules, runs the same
deterministic backend tools, and assembles a templated answer from their real results.
Responses are always labelled as demo responses in the API and UI."""
from __future__ import annotations

import json
import re

from app.ai.provider import LLMProvider, LLMResult, ToolCall, ToolSpec

DEMO_FOOTER = ("\n\n---\n*Demo mode — this answer was assembled by FitAI's rule-based engine from your real data, "
               "not generated by an LLM. Add a `GEMINI_API_KEY` to enable the AI coach.*")

INTENTS = [
    ("progress", r"lost|lose.*so far|progress|plateau|stopped|stuck|not (losing|decreasing)|trend|how am i doing|weight (history|change)"),
    ("next_week", r"next week|weekly plan|plan for the week|week('s)? (fitness )?plan"),
    ("preworkout", r"before (a |my |the )?(work(ing)? ?out|training|gym|exercis)|pre[- ]?workout"),
    ("calories", r"calorie|how much (should i )?eat|tdee|bmr|maintenance"),
    ("protein", r"protein|macro|carb|fat intake"),
    ("lose_x", r"lose \d+|how (can|do) i lose|lose weight|fat loss"),
    ("workout", r"workout|train|exercise|routine|gym|strength|stronger|muscle"),
    ("diet", r"diet|eat|meal|food|nutrition"),
]


def _intent(text: str) -> str:
    t = text.lower()
    for name, pat in INTENTS:
        if re.search(pat, t):
            return name
    return "general"


TOOLS_FOR = {
    "progress": [("get_weight_history", {"days": 30}), ("analyze_progress", {})],
    "next_week": [("calculate_calorie_target", {}), ("calculate_macros", {}), ("get_workout_history", {"days": 14}), ("generate_workout", {})],
    "preworkout": [("get_daily_nutrition", {})],
    "calories": [("calculate_calorie_target", {}), ("calculate_macros", {})],
    "protein": [("calculate_macros", {})],
    "lose_x": [("calculate_calorie_target", {}), ("get_weight_history", {"days": 30})],
    "workout": [("get_workout_history", {"days": 14}), ("generate_workout", {})],
    "diet": [("get_daily_nutrition", {}), ("calculate_macros", {})],
    "general": [("get_user_profile", {}), ("calculate_calorie_target", {})],
}


def _compose(intent: str, user_text: str, r: dict) -> str:
    out: list[str] = []
    cal = r.get("calculate_calorie_target") or {}
    mac = r.get("calculate_macros") or {}
    wh = r.get("get_weight_history") or {}
    ap = r.get("analyze_progress") or {}
    wo = r.get("generate_workout") or {}
    hist = r.get("get_workout_history") or {}
    nut = r.get("get_daily_nutrition") or {}

    if intent == "general":
        p = r.get("get_user_profile") or {}
        out.append(f"Hi {p.get('name', '').split(' ')[0]}! I'm your FitAI coach. I can calculate targets, review your "
                   "progress, and plan workouts and meals using your real data.")
    if intent in ("calories", "lose_x", "next_week", "general") and cal:
        out.append(f"Your estimated daily target is **{cal['calorie_target']} kcal** "
                   f"(TDEE ≈ {cal['tdee']} kcal, adjustment {cal['adjustment']:+} kcal for {cal['goal'].replace('_', ' ')}).")
        out.append(f"\n**Why:** {cal['rationale']}")
        for w in cal.get("warnings", []):
            out.append(f"\n> ⚠️ {w}")
    if intent == "lose_x":
        m = re.search(r"(\d+(?:\.\d+)?)\s*(kg|kilo|lb|pound)", user_text.lower())
        if m:
            amt = float(m.group(1)) * (0.4536 if m.group(2).startswith(("lb", "pound")) else 1)
            lo, hi = amt / 0.5, amt / 0.25
            out.append(f"\nAt a sustainable 0.25–0.5 kg per week, losing **{amt:.1f} kg** typically takes about "
                       f"**{lo:.0f}–{hi:.0f} weeks**. That's a typical range, not a guarantee.")
        out.append("\n**How to approach it**\n- Hit your calorie target most days (log meals to stay honest)\n"
                   "- Keep protein high to protect muscle\n- Strength train 3+ days a week and keep daily steps up\n"
                   "- Judge progress by weekly averages, not single weigh-ins")
    if mac and intent in ("calories", "protein", "diet", "next_week"):
        out.append(f"\n**Daily macros:** protein **{mac['protein_g']} g**, carbs **{mac['carbs_g']} g**, fat **{mac['fat_g']} g** "
                   f"(protein ≈ {mac['protein_g_per_kg']} g/kg). Spread protein across 3–5 meals of ~25–40 g.")
    if intent == "progress":
        recs = wh.get("records") or []
        if len(recs) < 2:
            out.append("I don't have enough weigh-ins yet to measure change. Log your weight 3–4 times a week in **Progress**.")
        else:
            ch = wh.get("change_in_window_kg")
            out.append(f"Over the last {wh.get('window_days')} days your logged weight changed by **{ch:+.1f} kg** "
                       f"({recs[0]['weight_kg']} → {recs[-1]['weight_kg']} kg).")
            if wh.get("trend_kg_per_week") is not None:
                out.append(f"Your 4-week trend is **{wh['trend_kg_per_week']:+.2f} kg/week**, and you're "
                           f"**{wh.get('goal_progress_pct')}%** of the way to your goal.")
            out.append("Remember: day-to-day changes include water and glycogen, so they don't necessarily mean fat change.")
        asked_stall = bool(re.search(r"stopped|stuck|plateau|not (losing|decreasing)", user_text.lower()))
        if asked_stall and not ap.get("plateau") and len(recs) >= 2:
            out.append("\n**Good news:** your stored weigh-ins don't show a true plateau yet — the weekly averages are still "
                       "moving. Daily readings can stall for a week or two because of water retention (salt, carbs, stress, "
                       "hard training), even while fat loss continues.")
        if ap.get("plateau"):
            out.append("\n**Possible plateau:** your last three weekly averages are nearly identical. Before cutting calories, "
                       "check logging accuracy (oils, drinks, weekends), daily steps and sleep. Plateaus of 2–3 weeks are common.")
        n = ap.get("nutrition") or {}
        if n:
            out.append(f"\n**Consistency:** food logged on {n.get('days_logged')} of the last 14 days; "
                       f"{ap.get('workouts_this_week')} {'workout' if ap.get('workouts_this_week') == 1 else 'workouts'} this week, streak {ap.get('streak')}.")
    if intent == "preworkout":
        out.append("**Pre-workout fuel (1–2 hours before):** a carb-forward meal with some protein and little fat, e.g. "
                   "a banana with Greek yogurt, oats with milk, or poha with sprouts. Within 30–45 minutes, keep it light "
                   "(a banana or a few dates). Hydrate well.")
        if nut.get("remaining"):
            out.append(f"\nYou have about **{max(0, nut['remaining']['calories']):.0f} kcal** and "
                       f"**{max(0, nut['remaining']['protein_g']):.0f} g protein** left for today.")
    if intent == "diet" and nut:
        t, tg = nut["totals"], nut["targets"]
        out.append(f"Today you've logged **{t['calories']} / {tg['calories']} kcal** and **{t['protein_g']} / {tg['protein_g']} g protein**.")
        out.append("\nBuild each meal around a protein source, add vegetables, and fit carbs around training. "
                   "The **Diet Planner** can generate a full day that matches your targets.")
    if intent in ("workout", "next_week") and wo:
        w = wo["workout"]
        if hist:
            out.append(f"\nYou've completed **{hist.get('completed_in_window')} workouts** in the last {hist.get('window_days')} days "
                       f"(current streak {hist.get('streak')}).")
        out.append(f"\n**Suggested session — {w['name']}** (~{w['duration_minutes']} min, {wo['split']}):")
        for e in w["exercises"]:
            out.append(f"- **{e['name']}** — {e['sets']} × {e['reps']}, rest {e['rest_seconds']}s")
        out.append(f"\n{wo['warmup']} Stop any exercise that causes pain.")
    if intent == "next_week":
        out.append("\n**Next week:** train on your planned days, aim for your calorie and protein targets on at least 5 days, "
                   "weigh in 3 times, and add 1–2 reps or a small load increase when all sets feel solid.")
    if intent == "general":
        out.append("\nTry asking: *How much protein do I need?*, *Am I making progress?* or *What workout should I do today?*")
    return "\n".join(out).strip() + DEMO_FOOTER


class MockProvider(LLMProvider):
    name = "mock"
    model = "rule-based-demo"
    is_real_llm = False

    def start(self, system, history, user_message):
        return {"user": user_message, "intent": _intent(user_message), "results": {}, "called": False}

    def step(self, state, tools: list[ToolSpec] | None) -> LLMResult:
        if not state["called"] and tools:
            state["called"] = True
            return LLMResult(tool_calls=[ToolCall(id=f"m{i}", name=n, args=a)
                                         for i, (n, a) in enumerate(TOOLS_FOR[state["intent"]])])
        return LLMResult(text=_compose(state["intent"], state["user"], state["results"]))

    def add_tool_results(self, state, results):
        for call, res in results:
            state["results"][call.name] = res

    def generate_json(self, system, prompt):
        return json.dumps({"error": "mock provider does not generate free-form JSON"})
